import { chromium } from '/workspace/node_modules/playwright/index.mjs';
import fs from 'node:fs';

const browser = await chromium.launch({ headless: true });
const ctx = await browser.newContext({ acceptDownloads: true, viewport: { width: 1440, height: 1200 } });
const page = await ctx.newPage();
page.on('pageerror', (e) => console.log('PAGE_ERROR:', String(e)));

await page.goto('http://localhost:5173/', { waitUntil: 'networkidle', timeout: 60000 });
await page.waitForTimeout(1500);

// Locate all elements named "Einzeiliges Textfeld" and "Beispiel laden"
const targets = await page.evaluate(() => {
  const out = [];
  document.querySelectorAll('button, [role="button"]').forEach((b, i) => {
    const name = (b.getAttribute('aria-label') || b.textContent || '').trim().slice(0, 40);
    if (/Einzeiliges Textfeld|Beispiel laden/.test(name)) {
      const r = b.getBoundingClientRect();
      out.push({ i, name, tag: b.tagName, visible: r.width > 0 && r.height > 0, x: Math.round(r.x), y: Math.round(r.y) });
    }
  });
  return out;
});
console.log('TARGETS:', JSON.stringify(targets, null, 1));

// Step 1: add a field group to the canvas
await page.getByRole('button', { name: 'Einfache Feldgruppe' }).first().click();
await page.waitForTimeout(1500);
const step1 = await page.evaluate(() => document.body.innerText.slice(0, 400));
console.log('AFTER_FIELDGROUP_TEXT_HEAD:', JSON.stringify(step1));

// Step 2: now click "Einzeiliges Textfeld" (module should land in the new field group)
await page.getByRole('button', { name: 'Einzeiliges Textfeld' }).first().click();
await page.waitForTimeout(1500);
await page.screenshot({ path: '/tmp/after-module-add.png', fullPage: true });

// Step 3: check model via download
const [download] = await Promise.all([
  page.waitForEvent('download', { timeout: 10000 }).catch(() => null),
  page.getByRole('button', { name: 'JSON herunterladen' }).first().click(),
]);
if (download) {
  const p = '/tmp/model-after-add.json';
  await download.saveAs(p);
  const model = JSON.parse(fs.readFileSync(p, 'utf8'));
  console.log('MODEL_AFTER_ADD:', JSON.stringify(model, null, 1).slice(0, 1200));
} else {
  console.log('NO_DOWNLOAD');
}
await browser.close();
EOF
